-- =====================================================================
-- Heartbeat · Box Office: reported worldwide totals (no daily numbers).
-- Run AFTER 013. Safe to run again (it replaces the rows it added before).
--  * All-time top 50 Indian grossers + the top 2026 films per language.
--  * Numbers are worldwide gross in ₹ crore, as reported. Some sources give a range (low–high).
--  * Every other 2026 Indian release is listed live from TMDB on the Box Office page ("No numbers reported").
-- =====================================================================
create table if not exists public.bo_reported (
  id         bigint generated always as identity primary key,
  title      text not null check (char_length(title) between 1 and 200),
  lang       text not null check (lang ~ '^[a-z]{2}$'),
  year       int  not null check (year between 1913 and 2100),
  release_date date,
  ww_low_cr  numeric(10,2) not null check (ww_low_cr >= 0),
  ww_high_cr numeric(10,2) check (ww_high_cr >= ww_low_cr),
  source     text not null check (char_length(source) <= 200),
  note       text check (char_length(note) <= 120),
  updated_at timestamptz not null default now(),
  unique (title, lang, year)
);

create or replace function public.box_office_reported() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'title', title, 'lang', lang, 'year', year, 'release_date', release_date,
    'low', ww_low_cr, 'high', ww_high_cr, 'source', source, 'note', note) order by ww_low_cr desc), '[]'::jsonb)
  from bo_reported
$$;

alter table public.bo_reported enable row level security;
revoke all on public.bo_reported from anon, authenticated;
revoke execute on function public.box_office_reported() from public;
grant execute on function public.box_office_reported() to anon, authenticated;

delete from public.bo_reported where source like 'Wikipedia:%';
